// Aiding Optimization: Pointer Aliasing (C99+)
void copy_data(int* restrict dest,
               const int* restrict src,
               size_t count) {
    // restrict guarantees dest/src do not overlap
    // Allows aggressive loop reordering/vectorization
    for (size_t i = 0; i < count; ++i) {
        dest[i] = src[i];
    }
}

// Disabling Optimization: Volatile Keyword
// Used for hardware registers or shared memory
volatile unsigned char IO_REGISTER;

void write_byte(unsigned char val) {
    // Compiler MUST generate actual store operation
    IO_REGISTER = val;
}
unsigned char read_byte() {
    // Compiler MUST generate actual load operation
    return IO_REGISTER;
}

// Hinting Vectorization (Example GCC/Clang Pragma)
// Used when compiler fails to deduce loop independence
void vector_add(float* a, float* b, int N) {
    #pragma GCC ivdep // Ignore Vector Dependencies
    for (int i = 0; i < N; ++i) {
        a[i] += b[i];
    }
}

